114	String getObjectDefinitionFromCreateQuery(const ASTPtr & query)
115	{
116	    ASTPtr query_clone = query->clone();
117	    auto * create = query_clone->as<ASTCreateQuery>();
118	
119	    if (!create)
120	        throw Exception(ErrorCodes::LOGICAL_ERROR, "Query '{}' is not CREATE query", serializeAST(*query));
121	
122	    /// Clean the query from temporary flags.
123	    cleanupObjectDefinitionFromTemporaryFlags(*create);
124	
125	    if (!create->is_dictionary)
126	        create->attach = true;
127	
128	    /// We remove everything that is not needed for ATTACH from the query.
129	    assert(!create->temporary);
130	    create->database.reset();
131	
132	    if (create->uuid != UUIDHelpers::Nil)
133	        create->setTable(TABLE_WITH_UUID_NAME_PLACEHOLDER);
134	
135	    WriteBufferFromOwnString statement_buf;
136	    formatAST(*create, statement_buf, false);
137	    writeChar('\n', statement_buf);
138	    return statement_buf.str();
139	}
